const $=id=>document.getElementById(id);
const money=v=>new Intl.NumberFormat("zh-CN",{style:"currency",currency:"CNY",minimumFractionDigits:2}).format(Number(v||0));
const num=(v,d=2)=>Number(v||0).toLocaleString("zh-CN",{minimumFractionDigits:d,maximumFractionDigits:d});
const pct=v=>v==null?"—":`${Number(v)>0?"+":""}${num(v)}%`;
const tone=v=>Number(v)>0?"positive":Number(v)<0?"negative":"flat";
const iso=d=>d.toISOString().slice(0,10);
async function fetchJson(url){let lastError;for(let attempt=0;attempt<2;attempt++){try{const r=await fetch(url);if(!r.ok){let detail=`请求失败 (${r.status})`;try{detail=(await r.json()).detail||detail}catch{}throw new Error(`${detail} · ${url}`)}return await r.json()}catch(e){lastError=e;if(attempt===0)await new Promise(resolve=>setTimeout(resolve,450))}}throw lastError}

function lineChart(rootId,rangeId,rows,valueKey,label,color="#35b980"){
 const root=$(rootId);if(!rows.length){root.innerHTML='<div class="empty">暂无走势数据</div>';return}const W=760,H=270,p={l:52,r:18,t:18,b:35},vals=rows.map(x=>Number(x[valueKey]));let min=Math.min(...vals),max=Math.max(...vals),pad=(max-min||Math.max(max*.01,1))*.3;min-=pad;max+=pad;const x=i=>p.l+i*(W-p.l-p.r)/Math.max(rows.length-1,1),y=v=>p.t+(max-v)*(H-p.t-p.b)/(max-min);let grid="";for(let i=0;i<4;i++){let yy=p.t+i*(H-p.t-p.b)/3,val=max-i*(max-min)/3;grid+=`<line x1="${p.l}" y1="${yy}" x2="${W-p.r}" y2="${yy}"/><text x="0" y="${yy+4}">${valueKey==='total_assets'?(val/10000).toFixed(1)+'万':val.toFixed(valueKey==='nav'?3:2)}</text>`}const points=rows.map((r,i)=>`${x(i)},${y(Number(r[valueKey]))}`).join(" ");root.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><defs><linearGradient id="area-${rootId}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".28"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><g class="grid">${grid}</g><polygon style="fill:url(#area-${rootId})" points="${p.l},${H-p.b} ${points} ${W-p.r},${H-p.b}"/><polyline class="line" style="stroke:${color}" points="${points}"/><circle style="stroke:${color}" cx="${x(rows.length-1)}" cy="${y(vals.at(-1))}" r="5"/></svg>`;$(rangeId).textContent=`${rows[0].date} — ${rows.at(-1).date} · ${label} ${valueKey==='total_assets'?money(vals.at(-1)):num(vals.at(-1),valueKey==='nav'?4:2)}`;
}

let currentStockSymbol=null;
let portfolioChartRows=[],fundChartRows=[];
function interactiveMetricChart(rootId,rangeId,tooltipId,rows,valueKey,color,formatter,valueLabel){const root=$(rootId);if(!rows.length){root.innerHTML='<div class="empty">所选区间没有数据</div>';return}const W=760,H=270,p={l:52,r:18,t:18,b:35},vals=rows.map(x=>Number(x[valueKey]));let min=Math.min(...vals),max=Math.max(...vals),pad=(max-min||Math.max(max*.01,1))*.3;min-=pad;max+=pad;const x=i=>p.l+i*(W-p.l-p.r)/Math.max(rows.length-1,1),y=v=>p.t+(max-v)*(H-p.t-p.b)/(max-min);let grid='';for(let i=0;i<4;i++){const yy=p.t+i*(H-p.t-p.b)/3,val=max-i*(max-min)/3;grid+=`<line x1="${p.l}" y1="${yy}" x2="${W-p.r}" y2="${yy}"/><text x="0" y="${yy+4}">${valueKey==='total_assets'?(val/10000).toFixed(1)+'万':val.toFixed(4)}</text>`}const points=rows.map((r,i)=>`${x(i)},${y(Number(r[valueKey]))}`).join(' '),uid=`hover-${rootId}`;root.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><g class="grid">${grid}</g><polyline class="line" style="stroke:${color}" points="${points}"/><line id="${uid}-line" class="crosshair" x1="0" x2="0" y1="${p.t}" y2="${H-p.b}"/><circle id="${uid}-dot" class="hover-dot" style="stroke:${color}" cx="0" cy="0" r="5"/></svg>`;$(rangeId).textContent=`${rows[0].date} — ${rows.at(-1).date} · ${valueLabel} ${valueKey==='total_assets'?money(vals.at(-1)):num(vals.at(-1),4)}`;const tip=$(tooltipId),cross=$(`${uid}-line`),dot=$(`${uid}-dot`);root.onmousemove=e=>{const rect=root.getBoundingClientRect(),localX=Math.max(0,Math.min(rect.width,e.clientX-rect.left)),plotX=localX/rect.width*W,index=Math.max(0,Math.min(rows.length-1,Math.round((plotX-p.l)/(W-p.l-p.r)*Math.max(rows.length-1,1)))),row=rows[index],cx=x(index),cy=y(Number(row[valueKey]));cross.setAttribute('x1',cx);cross.setAttribute('x2',cx);cross.classList.add('show');dot.setAttribute('cx',cx);dot.setAttribute('cy',cy);dot.classList.add('show');tip.innerHTML=formatter(row);tip.classList.add('show');tip.style.left=`${Math.min(localX+16,rect.width-tip.offsetWidth-8)}px`;tip.style.top=`${Math.max(8,e.clientY-rect.top-tip.offsetHeight-12)}px`};root.onmouseleave=()=>{cross.classList.remove('show');dot.classList.remove('show');tip.classList.remove('show')}}

function filterRecent(rows,days){if(!days||!rows.length)return rows;const end=new Date(`${rows.at(-1).date}T00:00:00`),start=new Date(end);start.setDate(end.getDate()-days);return rows.filter(x=>new Date(`${x.date}T00:00:00`)>=start)}
function drawPortfolioPeriod(days){const rows=filterRecent(portfolioChartRows,days);interactiveMetricChart('chart','chart-range','portfolio-tooltip',rows,'total_assets','#35b980',r=>`<b>${r.date}</b><div><span>总资产 ${money(r.total_assets)}</span><span>收益率 ${pct(r.return_percent)}</span><span>现金 ${money(r.cash)}</span><span>持仓市值 ${money(r.market_value)}</span></div>`,'总资产')}
function drawFundPeriod(days){const rows=filterRecent(fundChartRows,days);interactiveMetricChart('fund-chart','fund-range','fund-tooltip',rows,'nav','#365be8',r=>`<b>${r.date}</b><div><span>单位净值 ${num(r.nav,4)}</span><span>日涨跌 ${pct(r.daily_return)}</span></div>`,'最新净值')}
function interactiveStockChart(rows){const root=$("stock-chart");if(!rows.length){root.innerHTML='<div class="empty">所选区间没有交易数据</div>';$("stock-range").textContent='';return}const W=760,H=270,p={l:52,r:18,t:18,b:35},vals=rows.map(x=>Number(x.close));let min=Math.min(...vals),max=Math.max(...vals),pad=(max-min||Math.max(max*.01,1))*.3;min-=pad;max+=pad;const x=i=>p.l+i*(W-p.l-p.r)/Math.max(rows.length-1,1),y=v=>p.t+(max-v)*(H-p.t-p.b)/(max-min);let grid='';for(let i=0;i<4;i++){const yy=p.t+i*(H-p.t-p.b)/3,val=max-i*(max-min)/3;grid+=`<line x1="${p.l}" y1="${yy}" x2="${W-p.r}" y2="${yy}"/><text x="0" y="${yy+4}">${val.toFixed(2)}</text>`}const points=rows.map((r,i)=>`${x(i)},${y(Number(r.close))}`).join(' ');root.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><defs><linearGradient id="stockHoverArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d74d45" stop-opacity=".22"/><stop offset="1" stop-color="#d74d45" stop-opacity="0"/></linearGradient></defs><g class="grid">${grid}</g><polygon style="fill:url(#stockHoverArea)" points="${p.l},${H-p.b} ${points} ${W-p.r},${H-p.b}"/><polyline class="line" style="stroke:#d74d45" points="${points}"/><line id="stock-crosshair" class="crosshair" x1="0" x2="0" y1="${p.t}" y2="${H-p.b}"/><circle id="stock-hover-dot" class="hover-dot" cx="0" cy="0" r="5"/></svg>`;$("stock-range").textContent=`${rows[0].date} — ${rows.at(-1).date} · 共 ${rows.length} 个交易日`;const tip=$("stock-tooltip"),cross=$("stock-crosshair"),dot=$("stock-hover-dot");root.onmousemove=e=>{const rect=root.getBoundingClientRect(),localX=Math.max(0,Math.min(rect.width,e.clientX-rect.left)),plotX=localX/rect.width*W,index=Math.max(0,Math.min(rows.length-1,Math.round((plotX-p.l)/(W-p.l-p.r)*Math.max(rows.length-1,1)))),row=rows[index],cx=x(index),cy=y(Number(row.close));cross.setAttribute('x1',cx);cross.setAttribute('x2',cx);cross.classList.add('show');dot.setAttribute('cx',cx);dot.setAttribute('cy',cy);dot.classList.add('show');tip.innerHTML=`<b>${row.date}</b><div><span>开盘 ${num(row.open)}</span><span>最高 ${num(row.high)}</span><span>最低 ${num(row.low)}</span><span>收盘 ${num(row.close)}</span><span>涨跌 ${pct(row.change_percent)}</span><span>成交量 ${Number(row.volume||0).toLocaleString('zh-CN')}</span></div>`;tip.classList.add('show');const desired=localX+16;tip.style.left=`${Math.min(desired,rect.width-tip.offsetWidth-8)}px`;tip.style.top=`${Math.max(8,e.clientY-rect.top-tip.offsetHeight-12)}px`};root.onmouseleave=()=>{cross.classList.remove('show');dot.classList.remove('show');tip.classList.remove('show')}}

async function loadStockRange(days,startValue=null,endValue=null){if(!currentStockSymbol)return;const end=endValue?new Date(`${endValue}T00:00:00`):new Date(),start=startValue?new Date(`${startValue}T00:00:00`):new Date(end);start.setDate(start.getDate()-(startValue?0:days===0?7:days));$("stock-chart").innerHTML='<div class="empty">正在读取走势…</div>';try{const h=await fetchJson(`/api/v1/stocks/${encodeURIComponent(currentStockSymbol)}/history?start=${iso(start)}&end=${iso(end)}&adjust=qfq`);const rows=days===0&&!startValue?h.data.slice(-1):h.data;interactiveStockChart(rows)}catch(e){$("stock-chart").innerHTML=`<div class="empty">走势加载失败：${e.message}</div>`}}

function setupStockPeriods(){const today=new Date(),earliest=new Date();earliest.setDate(today.getDate()-90);$("stock-start").min=iso(earliest);$("stock-start").max=iso(today);$("stock-end").min=iso(earliest);$("stock-end").max=iso(today);$("stock-start").value=iso(earliest);$("stock-end").value=iso(today);document.querySelectorAll('[data-stock-days]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-stock-days]').forEach(x=>x.classList.remove('active'));button.classList.add('active');$("stock-custom-range").classList.add('hidden');loadStockRange(Number(button.dataset.stockDays))});$("stock-more").onclick=()=>{$("stock-custom-range").classList.toggle('hidden')};$("stock-apply-range").onclick=()=>{const start=$("stock-start").value,end=$("stock-end").value,error=$("stock-date-error");if(!start||!end||start>end){error.textContent='请选择正确的起止日期';return}const span=(new Date(end)-new Date(start))/86400000;if(span>90){error.textContent='查询区间最长为 90 天';return}error.textContent='';document.querySelectorAll('[data-stock-days]').forEach(x=>x.classList.remove('active'));loadStockRange(null,start,end)}}

function openTab(name){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));document.querySelectorAll('.tab-pane').forEach(x=>x.classList.toggle('active',x.id===`tab-${name}`));window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>openTab(x.dataset.tab));

function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function renderDecisions(rows=[]){const root=$("decision-list"),labels={WATCH:'继续观察',BUY:'买入',ADD:'加仓',REDUCE:'减仓',SELL:'卖出'},statusLabels={FILLED:'已成交',PENDING_NAV:'等待净值',PENDING:'待处理',CANCELLED:'已撤销',NO_ORDER:'未产生订单'};const operation=o=>o.side==='WATCH'?`<div class="decision-operation"><span>操作</span><strong>继续持有</strong><p>${escapeHtml(o.description||'本次未产生买卖订单')}</p></div>`:`<div class="decision-operation"><span>操作</span><strong>${labels[o.side]||escapeHtml(o.side)} ${escapeHtml(o.fund_name||o.fund_code||'')}</strong><p>${o.gross_amount?`金额 ${money(o.gross_amount)}`:`份额 ${num(o.shares,4)}`} · ${statusLabels[o.status]||escapeHtml(o.status||'待处理')}${o.nav?` · 净值 ${num(o.nav,4)}`:''}</p></div>`;root.innerHTML=rows.length?rows.map(d=>`<article class="decision-card"><div class="decision-top"><time>${escapeHtml(d.decision_date||'—')}</time></div>${(d.operations||[]).map(operation).join('')}<h3>决策与处理</h3><p>${escapeHtml(d.reason||d.market_observation||'—')}</p></article>`).join(''):'<div class="empty">暂无 AI 决策记录</div>'}

function renderPortfolio(data){const s=data.summary,cashRate=Number(s.initial_cash)?Number(s.cash)/Number(s.initial_cash)*100:0;$("asof").textContent=`数据日期 ${data.period.as_of}`;$("period").textContent=`${data.period.start} — ${data.period.end}`;$("status-badge").textContent=data.status==="ACTIVE"?"运行中":"已结束";$("total-assets").textContent=money(s.total_assets);$("initial-cash").textContent=money(s.initial_cash);$("total-pnl").textContent=`${Number(s.total_pnl)>=0?"盈利":"亏损"} ${money(Math.abs(Number(s.total_pnl)))}`;$("total-pnl").className=`pnl ${tone(s.total_pnl)}`;$("return-rate").textContent=pct(s.return_percent);$("return-rate").className=tone(s.return_percent);$("invested-capital").textContent=money(s.invested_capital);$("invested-rate").textContent=`占初始资金 ${num(s.invested_percent)}%`;$("cash").textContent=money(s.cash);$("cash-rate").textContent=`占初始资金 ${num(cashRate)}%`;$("invested-center").textContent=`${num(s.invested_percent)}%`;$("donut").style.setProperty("--invested",`${Number(s.invested_percent)*3.6}deg`);$("fund-allocation").textContent=`${num(s.invested_percent)}%`;$("cash-allocation").textContent=`${num(100-Number(s.invested_percent))}%`;$("market-weight").textContent=`${num(s.market_weight_percent)}%`;$("position-count").textContent=`${data.positions.length} 项资产`;$("holdings-body").innerHTML=data.positions.length?data.positions.map(p=>`<tr><td><div class="asset-name"><a class="asset-link" data-fund="${p.code}"><b>${p.name}</b><span>${p.code} · 点击查看详情</span></a></div></td><td>${num(p.shares,4)}</td><td>${num(p.nav,4)}</td><td>${money(p.cost)}</td><td><b>${money(p.market_value)}</b></td><td class="${tone(p.pnl)}"><b>${pct(p.return_percent)}</b><small>${money(p.pnl)}</small></td><td>${num(p.allocation_percent)}%</td></tr>`).join(""):'<tr><td colspan="7" class="empty">暂无持仓</td></tr>';document.querySelectorAll('[data-fund]').forEach(x=>x.onclick=()=>loadFund(x.dataset.fund,true));$("orders").innerHTML=data.orders.length?data.orders.map(o=>`<div class="order"><span class="order-icon ${o.side.toLowerCase()}">${o.side==="BUY"?"买":"卖"}</span><div><b>${o.fund_name}</b><p>${o.decision_date} · ${o.order_id}</p></div><div class="order-value"><b>${o.side==="BUY"?money(o.gross_amount):`${num(o.shares,4)} 份`}</b><span>${o.status==="FILLED"?"已成交":"待确认"}</span></div></div>`).join(""):'<div class="empty">暂无交易</div>';portfolioChartRows=data.valuations;drawPortfolioPeriod(0);$("loading").classList.add("hidden");$("content").classList.remove("hidden")}

async function loadFund(code,switchTab=false){if(switchTab)openTab('fund');$("fund-results").innerHTML='<div class="search-message">正在读取基金最新状态…</div>';$("fund-detail").classList.add('hidden');try{const r=await fetch(`/api/v1/funds/${encodeURIComponent(code)}`);if(!r.ok)throw new Error((await r.json()).detail||'基金加载失败');const d=await r.json();$("fund-results").innerHTML='';$("fund-name").textContent=d.name;$("fund-code").textContent=d.code;$("fund-type").textContent=d.type;$("fund-date").textContent=d.latest.date;$("fund-nav").textContent=num(d.latest.nav,4);$("fund-daily").textContent=`最新变化 ${Number(d.latest.nav_change)>0?'+':''}${num(d.latest.nav_change,4)} · ${pct(d.latest.daily_return)}`;$("fund-daily").className=tone(d.latest.daily_return);for(const [id,v] of [['fund-r1w',d.returns.one_week],['fund-r1m',d.returns.one_month],['fund-r3m',d.returns.three_months],['fund-r1y',d.returns.one_year],['fund-dd',d.max_drawdown_one_year]]){$(id).textContent=pct(v);$(id).className=tone(v)}fundChartRows=d.history;drawFundPeriod(365);currentFundCode=d.code;updateFundTrading(d.code);$("fund-detail").classList.remove('hidden')}catch(e){$("fund-results").innerHTML=`<div class="search-message">${e.message}</div>`}}

function renderPager(kind,p,onPage){const root=$(`${kind}-pager`);if(p.total<=p.page_size){root.classList.add('hidden');root.innerHTML='';return}root.classList.remove('hidden');root.innerHTML=`<button ${p.page<=1?'disabled':''} data-page="${p.page-1}">上一页</button><span>第 <b>${p.page}</b> / ${p.total_pages} 页 · 共 ${p.total} 条</span><button ${p.page>=p.total_pages?'disabled':''} data-page="${p.page+1}">下一页</button>`;root.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>onPage(Number(x.dataset.page)))}
async function searchFunds(page=1){const q=$("fund-query").value.trim();if(!q)return;if(/^\d{6}$/.test(q)){loadFund(q);return}$("fund-results").innerHTML='<div class="search-message">正在搜索基金…</div>';$("fund-detail").classList.add('hidden');try{const data=await fetchJson(`/api/v1/funds?q=${encodeURIComponent(q)}&page=${page}&page_size=50`),rows=data.items;$("fund-results").innerHTML=rows.length?rows.map(x=>`<button class="result-card" data-result-fund="${x.code}"><div><b>${x.name}</b><span>${x.code}</span></div><em>${x.type}</em></button>`).join(''):'<div class="search-message">没有找到匹配的基金</div>';document.querySelectorAll('[data-result-fund]').forEach(x=>x.onclick=()=>loadFund(x.dataset.resultFund));renderPager('fund',data.pagination,searchFunds)}catch(e){$("fund-pager").classList.add('hidden');$("fund-results").innerHTML=`<div class="search-message">连接失败，请稍后重试：${e.message}</div>`}}
$("fund-search").onsubmit=e=>{e.preventDefault();searchFunds(1)};

async function loadStock(symbol){$("stock-results").innerHTML='<div class="search-message">正在读取股票行情…</div>';$("stock-detail").classList.add('hidden');currentStockSymbol=symbol;const end=new Date(),start=new Date();start.setDate(end.getDate()-90);try{const [q,h]=await Promise.all([fetchJson(`/api/v1/stocks/${encodeURIComponent(symbol)}/quote`),fetchJson(`/api/v1/stocks/${encodeURIComponent(symbol)}/history?start=${iso(start)}&end=${iso(end)}&adjust=qfq`)]);$("stock-results").innerHTML='';$("stock-name").textContent=q.name;$("stock-code").textContent=q.symbol;$("stock-exchange").textContent=q.exchange;$("stock-price").textContent=num(q.price);$("stock-change").textContent=`${q.timestamp?q.timestamp.slice(0,10)+' · ':''}较前收 ${Number(q.change)>0?'+':''}${num(q.change)} · ${pct(q.change_percent)}`;$("stock-change").className=tone(q.change);for(const [id,v,suffix] of [['stock-open',q.open,''],['stock-high',q.high,''],['stock-low',q.low,''],['stock-prev',q.previous_close,''],['stock-turnover',q.turnover_rate,'%']])$(id).textContent=v==null?'—':num(v)+suffix;document.querySelectorAll('[data-stock-days]').forEach(x=>x.classList.toggle('active',x.dataset.stockDays==='90'));$("stock-custom-range").classList.add('hidden');interactiveStockChart(h.data);$("stock-detail").classList.remove('hidden')}catch(e){$("stock-results").innerHTML=`<div class="search-message">${e.message}</div>`}}

async function searchStocks(page=1){const q=$("stock-query").value.trim();if(!q)return;$("stock-results").innerHTML='<div class="search-message">正在搜索股票…</div>';$("stock-detail").classList.add('hidden');try{const data=await fetchJson(`/api/v1/stocks?q=${encodeURIComponent(q)}&page=${page}&page_size=50`),rows=data.items;if(rows.length===1&&/^\d/.test(q)){loadStock(rows[0].symbol);return}$("stock-results").innerHTML=rows.length?rows.map(x=>`<button class="result-card" data-result-stock="${x.symbol}"><div><b>${x.name}</b><span>${x.symbol}</span></div><em>${x.exchange}</em></button>`).join(''):'<div class="search-message">没有找到匹配的股票</div>';document.querySelectorAll('[data-result-stock]').forEach(x=>x.onclick=()=>loadStock(x.dataset.resultStock));renderPager('stock',data.pagination,searchStocks)}catch(e){$("stock-pager").classList.add('hidden');$("stock-results").innerHTML=`<div class="search-message">连接失败，请稍后重试：${e.message}</div>`}}
$("stock-search").onsubmit=e=>{e.preventDefault();searchStocks(1)};

let signedInUser=null,authMode='login',lastUserPortfolio=null,currentFundCode=null,userPreviewRows=[],userPreviewCode=null;
function apiErrorMessage(payload,status){const detail=payload?.detail;if(typeof detail==='string')return detail;if(Array.isArray(detail)){return detail.map(item=>{const field=item.loc?.at(-1);if(field==='password'&&item.type==='string_too_short')return '密码至少需要 8 位';if(field==='username'&&item.type==='string_too_short')return '用户名至少需要 3 位';if(field==='username'&&item.type==='string_too_long')return '用户名不能超过 24 位';return item.msg||'输入内容不符合要求'}).join('；')}return `请求失败 (${status})`}
async function apiRequest(url,options={}){const response=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});if(!response.ok){let payload={};try{payload=await response.json()}catch(_){}throw new Error(`${apiErrorMessage(payload,response.status)} · ${url}`)}return response.status===204?null:response.json()}
function openAuth(){$("auth-modal").classList.remove('hidden');$("auth-message").textContent='';$("auth-username").focus()}
function closeAuth(){$("auth-modal").classList.add('hidden')}
function setUser(user){signedInUser=user;$("auth-button").classList.toggle('hidden',!!user);$("user-chip").classList.toggle('hidden',!user);$("logout-button").classList.toggle('hidden',!user);$("user-chip").textContent=user?user.username:'';$("user-login-prompt").classList.toggle('hidden',!!user);$("user-portfolio").classList.toggle('hidden',!user);if(user)loadUserPortfolio();else{lastUserPortfolio=null;$("fund-trade-actions").classList.add('hidden')}}
async function checkAuth(){try{setUser(await apiRequest('/api/v1/auth/me'))}catch(_){setUser(null)}}
async function loadUserPortfolio(){try{const data=await apiRequest('/api/v1/user/portfolio'),a=data.account,s=data.summary;lastUserPortfolio=data;$("user-total").textContent=money(s.total_assets);$("user-pnl").textContent=`${pct(s.return_percent)} · ${money(s.pnl)}`;$("user-pnl").className=tone(s.pnl);$("user-cash").textContent=money(a.cash_available);$("user-frozen").textContent=money(a.cash_frozen);$("user-market").textContent=money(s.market_value);$("user-positions").innerHTML=data.positions.length?data.positions.map(p=>`<div class="user-row"><div><b>${p.fund_name}</b><span>${p.fund_code}</span></div><div>持有份额<b>${num(p.shares,4)}</b></div><div>持仓成本<b>${money(p.cost_basis)}</b></div><div>当前市值<b>${money(p.market_value)}</b></div><div class="${tone(p.pnl)}">盈亏<b>${money(p.pnl)}</b></div><div class="holding-actions"><button data-position-sell="${p.fund_code}" data-available-shares="${Number(p.shares)-Number(p.shares_frozen)}">卖出</button></div></div>`).join(''):'<div class="empty">暂无基金持仓</div>';$("user-orders").innerHTML=data.orders.length?data.orders.map(o=>`<div class="user-row"><div><b>${o.side==='BUY'?'买入':'卖出'} ${o.fund_name}</b><span>${o.created_at.slice(0,16).replace('T',' ')} · 订单 #${o.id}</span></div><div>状态<b>${o.status==='PENDING'?'可撤销':o.status==='WAITING_NAV'?'等待净值':o.status==='WAITING_CONFIRMATION'?'等待份额确认':o.status==='FILLED'?'已确认':'已撤销'}</b></div><div>金额/份额<b>${o.side==='BUY'?money(o.gross_amount):`${num(o.shares,4)}份`}</b></div><div>净值日<b>${o.nav_date}</b></div>${o.cancelable?`<button data-cancel-order="${o.id}">撤销</button>`:'<div></div>'}</div>`).join(''):'<div class="empty">暂无订单</div>';document.querySelectorAll('[data-cancel-order]').forEach(b=>b.onclick=async()=>{if(!confirm('确认撤销这笔待处理订单？'))return;try{await apiRequest(`/api/v1/user/orders/${b.dataset.cancelOrder}/cancel`,{method:'POST'});loadUserPortfolio()}catch(e){alert(e.message)}});document.querySelectorAll('[data-position-sell]').forEach(b=>b.onclick=()=>prepareSell(b.dataset.positionSell,b.dataset.availableShares));if(currentFundCode)updateFundTrading(currentFundCode);$("trade-rules").textContent=`交易说明：${data.rules.confirmation}；截止时间前可撤销，之后进入等待净值和份额确认阶段。${data.rules.income}。${data.rules.default_fee_notice}。` }catch(e){if(e.message.includes('登录'))setUser(null)}}
function prepareSell(code,shares){openTab('user');$("sell-code").value=code;$("sell-shares").value=Number(shares).toFixed(4);$("sell-code").closest('.trade-card').scrollIntoView({behavior:'smooth',block:'center'})}
function updateFundTrading(code){const root=$("fund-trade-actions");if(!signedInUser){root.classList.add('hidden');return}root.classList.remove('hidden');const position=lastUserPortfolio?.positions?.find(p=>p.fund_code===code),available=position?Number(position.shares)-Number(position.shares_frozen):0;$("fund-trade-holding").textContent=position?`当前持有 ${num(position.shares,4)} 份，可卖 ${num(available,4)} 份`:'当前未持有，可模拟买入';$("detail-sell-wrap").classList.toggle('hidden',available<=0);$("detail-sell-button").classList.toggle('hidden',available<=0);$("detail-sell-shares").max=available>0?available:'';if(available>0)$("detail-sell-shares").value=available.toFixed(4);$("detail-trade-message").textContent=''}
function drawUserFundPreview(days=90){const rows=filterRecent(userPreviewRows,days);interactiveMetricChart('user-preview-chart','user-preview-range','user-preview-tooltip',rows,'nav','#365be8',r=>`<b>${r.date}</b><div><span>单位净值 ${num(r.nav,4)}</span><span>日涨跌 ${pct(r.daily_return)}</span></div>`,'最新净值')}
async function loadUserFundPreview(code){const root=$("user-fund-preview");root.classList.remove('hidden');$("user-preview-select").classList.add('hidden');$("user-preview-name").textContent='正在读取基金数据…';$("user-preview-code").textContent='';try{const d=await fetchJson(`/api/v1/funds/${encodeURIComponent(code)}`);userPreviewCode=d.code;userPreviewRows=d.history;$("user-preview-select").classList.remove('hidden');$("user-preview-name").textContent=d.name;$("user-preview-code").textContent=d.code;$("user-preview-type").textContent=d.type;$("user-preview-nav").textContent=num(d.latest.nav,4);$("user-preview-date").textContent=d.latest.date;$("user-preview-daily").textContent=`较前一净值 ${Number(d.latest.nav_change)>0?'+':''}${num(d.latest.nav_change,4)} · ${pct(d.latest.daily_return)}`;$("user-preview-daily").className=tone(d.latest.daily_return);for(const [id,value] of [['user-preview-week',d.returns.one_week],['user-preview-month',d.returns.one_month],['user-preview-quarter',d.returns.three_months]]){$(id).textContent=pct(value);$(id).className=tone(value)}document.querySelectorAll('[data-user-preview-days]').forEach(x=>x.classList.toggle('active',x.dataset.userPreviewDays==='90'));drawUserFundPreview(90);root.scrollIntoView({behavior:'smooth',block:'nearest'})}catch(e){userPreviewCode=null;userPreviewRows=[];$("user-preview-select").classList.add('hidden');$("user-preview-type").textContent='不可用';$("user-preview-code").textContent='';$("user-preview-name").textContent=`暂不显示：${e.message}`;$("user-preview-nav").textContent='—';$("user-preview-date").textContent='—';$("user-preview-daily").textContent='—';$("user-preview-chart").innerHTML='<div class="empty">该基金暂时无法获取完整净值数据</div>';$("user-preview-range").textContent=''}}
document.querySelectorAll('[data-user-preview-days]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-user-preview-days]').forEach(x=>x.classList.remove('active'));button.classList.add('active');drawUserFundPreview(Number(button.dataset.userPreviewDays))});$("user-preview-select").onclick=()=>{if(!userPreviewCode)return;$("buy-code").value=userPreviewCode;$("buy-message").textContent='已选择上方基金，请输入买入金额';$("buy-amount").focus();$("buy-code").closest('.trade-card').scrollIntoView({behavior:'smooth',block:'center'})};async function searchUserFunds(page=1){const q=$("user-fund-query").value.trim(),root=$("user-fund-results");if(!q)return;root.innerHTML='<div class="search-message">正在查找基金…</div>';$("user-fund-preview").classList.add('hidden');try{const data=await fetchJson(`/api/v1/funds?q=${encodeURIComponent(q)}&page=${page}&page_size=12&tradable_only=true`),rows=data.items;root.innerHTML=rows.length?rows.map(f=>`<button class="user-fund-result" data-user-fund="${f.code}"><div><b>${f.name}</b><span>${f.code}</span></div><em>查看并选择</em></button>`).join(''):'<div class="search-message">没有找到可预览且可申购的基金</div>';document.querySelectorAll('[data-user-fund]').forEach(b=>b.onclick=()=>loadUserFundPreview(b.dataset.userFund));renderPager('user-fund',data.pagination,searchUserFunds)}catch(e){$("user-fund-pager").classList.add('hidden');root.innerHTML=`<div class="search-message">${e.message}</div>`}}
$("user-fund-search-button").onclick=searchUserFunds;$("user-fund-query").onkeydown=e=>{if(e.key==='Enter')searchUserFunds()};
$("detail-buy-button").onclick=async()=>{const message=$("detail-trade-message");try{const result=await apiRequest('/api/v1/user/orders/buy',{method:'POST',body:JSON.stringify({fund_code:currentFundCode,amount:$("detail-buy-amount").value})});message.textContent=`买入已提交，净值日 ${result.nav_date}`;await loadUserPortfolio()}catch(e){message.textContent=e.message}};
$("detail-sell-button").onclick=async()=>{const message=$("detail-trade-message");try{const result=await apiRequest('/api/v1/user/orders/sell',{method:'POST',body:JSON.stringify({fund_code:currentFundCode,shares:$("detail-sell-shares").value})});message.textContent=`卖出已提交，净值日 ${result.nav_date}`;await loadUserPortfolio()}catch(e){message.textContent=e.message}};$("auth-button").onclick=openAuth;$("prompt-login").onclick=openAuth;$("auth-close").onclick=closeAuth;$("auth-modal").onclick=e=>{if(e.target===$("auth-modal"))closeAuth()};document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>{authMode=b.dataset.authMode;document.querySelectorAll('[data-auth-mode]').forEach(x=>x.classList.toggle('active',x===b));$("auth-title").textContent=authMode==='login'?'欢迎回来':'创建模拟账户';$("auth-submit").textContent=authMode==='login'?'登录':'创建账户';$("auth-message").textContent=''});$("auth-submit").onclick=async()=>{const username=$("auth-username").value.trim(),password=$("auth-password").value,message=$("auth-message");if(username.length<3){message.textContent='用户名至少需要 3 位';return}if(password.length<8){message.textContent='密码至少需要 8 位';return}message.textContent='正在提交…';try{const user=await apiRequest(`/api/v1/auth/${authMode}`,{method:'POST',body:JSON.stringify({username,password})});setUser(user);$("auth-password").value='';closeAuth();openTab('user')}catch(e){message.textContent=e.message}};$("auth-password").onkeydown=e=>{if(e.key==='Enter')$("auth-submit").click()};$("logout-button").onclick=async()=>{try{await apiRequest('/api/v1/auth/logout',{method:'POST'})}finally{setUser(null);openTab('ai')}};
$("buy-submit").onclick=async()=>{const message=$("buy-message");try{const result=await apiRequest('/api/v1/user/orders/buy',{method:'POST',body:JSON.stringify({fund_code:$("buy-code").value.trim(),amount:$("buy-amount").value})});message.textContent=`买入订单已提交，净值日 ${result.nav_date}`;loadUserPortfolio()}catch(e){message.textContent=e.message}};$("sell-submit").onclick=async()=>{const message=$("sell-message");try{const result=await apiRequest('/api/v1/user/orders/sell',{method:'POST',body:JSON.stringify({fund_code:$("sell-code").value.trim(),shares:$("sell-shares").value})});message.textContent=`卖出订单已提交，净值日 ${result.nav_date}`;loadUserPortfolio()}catch(e){message.textContent=e.message}};

document.querySelectorAll('[data-portfolio-days]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-portfolio-days]').forEach(x=>x.classList.remove('active'));button.classList.add('active');drawPortfolioPeriod(Number(button.dataset.portfolioDays))});
document.querySelectorAll('[data-fund-days]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-fund-days]').forEach(x=>x.classList.remove('active'));button.classList.add('active');drawFundPeriod(Number(button.dataset.fundDays))});
