// Personal holding presets affect only the signed-in user's simulated account.
function installPresetHoldings(){
  const holdingsRoot=$("user-positions");
  if(!holdingsRoot||$("preset-submit"))return;
  const tradeGrid=holdingsRoot;
  tradeGrid.insertAdjacentHTML("beforebegin",`<section class="panel preset-holdings"><div class="panel-head"><div><p class="eyebrow">EXISTING HOLDING</p><h2>预设已有基金持仓</h2></div><span class="quiet">仅记录个人模拟账户</span></div><p class="preset-intro">按当前净值和盈亏比例反推持仓成本；卖出手续费留空即为 0%。</p><div class="preset-grid"><label>基金代码<input id="preset-code" maxlength="6" inputmode="numeric" placeholder="例如 018099"></label><label>持有份额<input id="preset-shares" type="number" min="0.0001" step="0.0001" placeholder="例如 1000"></label><label>盈亏方向<select id="preset-pnl-direction"><option value="profit">盈利</option><option value="loss">亏损</option></select></label><label>盈亏比例 %<input id="preset-pnl-percent" type="number" min="0" max="99.9999" step="0.01" placeholder="例如 8.5"></label><label>卖出手续费 %（可选）<input id="preset-sell-fee" type="number" min="0" max="100" step="0.01" placeholder="留空为 0"></label></div><button id="preset-submit" class="preset-submit">添加预设持仓</button><p id="preset-message" class="trade-message"></p></section>`);
  const style=document.createElement("style");style.textContent=`.preset-holdings{margin-top:12px}.preset-intro{color:var(--muted);font-size:12px}.preset-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.preset-grid label{display:block;color:var(--muted);font-size:12px}.preset-grid input,.preset-grid select{box-sizing:border-box;display:block;width:100%;margin-top:6px;padding:10px;border:1px solid var(--line);border-radius:9px;background:#fff;font-size:14px}.preset-submit{margin-top:15px;border:0;border-radius:9px;background:var(--green);color:#fff;padding:10px 16px;font-weight:700;cursor:pointer}@media(max-width:760px){.preset-grid{grid-template-columns:1fr 1fr}}`;document.head.append(style);
  $("preset-submit").onclick=async()=>{const message=$("preset-message"),fee=$("preset-sell-fee").value.trim();try{const result=await apiRequest("/api/v1/user/positions/preset",{method:"POST",body:JSON.stringify({fund_code:$("preset-code").value.trim(),shares:$("preset-shares").value,pnl_direction:$("preset-pnl-direction").value,pnl_percent:$("preset-pnl-percent").value,sell_fee_percent:fee===""?null:fee})});message.textContent=`已添加 ${result.fund_name}，成本 ${money(result.cost_basis)}`;await loadUserPortfolio()}catch(e){message.textContent=e.message}};
}
const baseLoadUserPortfolio=loadUserPortfolio;
loadUserPortfolio=async function(){await baseLoadUserPortfolio();if(!lastUserPortfolio)return;const root=$("user-positions");root.innerHTML=lastUserPortfolio.positions.length?lastUserPortfolio.positions.map(p=>`<div class="user-row"><div><b>${p.fund_name}</b><span>${p.fund_code}</span></div><div>持有份额<b>${num(p.shares,4)}</b></div><div>持仓成本<b>${money(p.cost_basis)}</b></div><div>当前市值<b>${money(p.market_value)}</b></div><div class="${tone(p.pnl)}">盈亏<b>${money(p.pnl)} · ${pct(p.return_percent)}</b><span>卖出手续费 ${p.sell_fee_rate===null||p.sell_fee_rate===undefined?'按规则':pct(Number(p.sell_fee_rate)*100)}</span></div><div class="holding-actions"><button data-position-sell="${p.fund_code}" data-available-shares="${Number(p.shares)-Number(p.shares_frozen)}">卖出</button></div></div>`).join(""):'<div class="empty">暂无基金持仓</div>';document.querySelectorAll("[data-position-sell]").forEach(b=>b.onclick=()=>prepareSell(b.dataset.positionSell,b.dataset.availableShares));};
installPresetHoldings();
function installUserPortfolioRefresh(){const root=$('user-portfolio'),summary=root?.querySelector('.user-summary');if(!root||!summary||$('user-portfolio-refresh'))return;summary.insertAdjacentHTML('beforebegin','<div class="portfolio-refresh-toolbar"><div><b>持仓估值</b><span id="user-refresh-status">刷新你的基金持仓与独立 AI 持仓</span></div><button id="user-portfolio-refresh" type="button"><i>↻</i>刷新全部持仓</button></div>');if(!$('user-refresh-style')){const style=document.createElement('style');style.id='user-refresh-style';style.textContent='.portfolio-refresh-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 14px;padding:12px 14px;border:1px solid #cfe4d8;border-radius:13px;background:linear-gradient(100deg,#f7fcf8,#ebf7f0)}.portfolio-refresh-toolbar b{font-size:13px}.portfolio-refresh-toolbar span{margin-left:10px;color:var(--muted);font-size:12px}.portfolio-refresh-toolbar button{border:0;border-radius:9px;background:var(--green);color:#fff;padding:9px 13px;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap;box-shadow:0 4px 12px rgba(18,107,80,.16)}.portfolio-refresh-toolbar button:disabled{opacity:.65;cursor:wait}.portfolio-refresh-toolbar button i{font-style:normal;font-size:15px;margin-right:5px}@media(max-width:600px){.portfolio-refresh-toolbar{align-items:flex-start;flex-direction:column;gap:9px}.portfolio-refresh-toolbar span{display:block;margin:4px 0 0}.portfolio-refresh-toolbar button{width:100%}}';document.head.append(style)}$('user-portfolio-refresh').onclick=async()=>{const button=$('user-portfolio-refresh'),status=$('user-refresh-status');button.disabled=true;status.textContent='正在刷新你的基金与独立 AI 持仓…';try{const [data,aiData]=await Promise.all([apiRequest('/api/v1/user/portfolio/refresh',{method:'POST'}),apiRequest('/api/v1/user/ai/refresh',{method:'POST'})]);lastUserPortfolio=data;await loadUserPortfolio();if($('tab-user-ai')?.classList.contains('active')){renderUserAi(aiData);renderAiChat(aiData)}const dates=[...new Set([...(data.positions||[]),...(aiData.positions||[])].map(p=>p.nav?`净值日期 ${p.as_of||'—'}`:null).filter(Boolean))];status.textContent=`已刷新 ${data.refreshed_at.slice(11,16)}${dates.length?` · ${dates.join('、')}`:''}`}catch(error){status.textContent=`刷新失败：${error.message}`}finally{button.disabled=false}}}
installUserPortfolioRefresh();
function useSequentialPortfolioRefresh(){const button=$('user-portfolio-refresh'),status=$('user-refresh-status');if(!button||!status)return;button.onclick=async()=>{button.disabled=true;status.textContent='正在刷新你的基金持仓…';try{const data=await apiRequest('/api/v1/user/portfolio/refresh',{method:'POST'});lastUserPortfolio=data;await loadUserPortfolio();status.textContent='个人持仓已刷新，正在刷新独立 AI 持仓…';let aiData=null,aiError=null;try{aiData=await apiRequest('/api/v1/user/ai/refresh',{method:'POST'})}catch(error){aiError=error}if(aiData&&$('tab-user-ai')?.classList.contains('active')){renderUserAi(aiData);renderAiChat(aiData)}const dates=[...new Set([...(data.positions||[]),...(aiData?.positions||[])].map(p=>p.nav?`净值日期 ${p.as_of||'—'}`:null).filter(Boolean))];status.textContent=aiError?`个人持仓已刷新；独立 AI 刷新稍后重试：${aiError.message}`:`已刷新 ${data.refreshed_at.slice(11,16)}${dates.length?` · ${dates.join('、')}`:''}`}catch(error){status.textContent=`个人持仓刷新失败：${error.message}`}finally{button.disabled=false}}}
useSequentialPortfolioRefresh();
function setupPresetFundLookup(){
  const code=$("preset-code"),submit=$("preset-submit"),amountInput=$("preset-shares");
  if(!code||!submit||$("preset-lookup"))return;
  const label=code.closest("label");
  const amountLabel=amountInput.closest("label");
  amountLabel.childNodes[0].nodeValue='当前持有金额';amountInput.id='preset-amount';amountInput.min='0.01';amountInput.step='0.01';amountInput.placeholder='例如 1000 元';
  amountLabel.insertAdjacentHTML('beforeend','<small id="preset-share-estimate" class="preset-share-estimate">查询净值后自动换算份额</small>');
  label.insertAdjacentHTML("beforeend",'<button id="preset-lookup" type="button" class="preset-lookup">查询当前情况</button>');
  submit.insertAdjacentHTML("afterend",'<div id="preset-fund-status" class="preset-fund-status">输入 6 位基金代码后可先查询当前净值。</div>');
  const style=document.createElement("style");style.textContent='.preset-lookup{margin-top:7px;border:1px solid var(--line);border-radius:7px;background:#fff;color:var(--green);padding:7px 9px;font-size:12px;font-weight:700;cursor:pointer}.preset-fund-status{margin-top:10px;padding:10px 12px;border-radius:8px;background:#f4f8f6;color:var(--muted);font-size:12px;line-height:1.6}.preset-fund-status b{color:var(--ink)}.preset-share-estimate{display:block;margin-top:6px;color:var(--green);font-size:11px;line-height:1.4}';document.head.append(style);
  const showEstimatedShares=()=>{const nav=Number(amountInput.dataset.nav),amount=Number(amountInput.value),estimate=$("preset-share-estimate");estimate.textContent=nav>0&&amount>0?`按最新净值预计持有 ${num(amount/nav,4)} 份（提交时将按服务端最新净值复算）`:'查询净值后自动换算份额'};
  const lookup=async()=>{const status=$("preset-fund-status"),fundCode=code.value.trim();if(!/^\d{6}$/.test(fundCode)){status.textContent='请输入正确的 6 位基金代码。';return}status.textContent='正在查询基金当前情况…';try{const data=await fetchJson(`/api/v1/funds/${encodeURIComponent(fundCode)}`),latest=data.latest;amountInput.dataset.nav=latest.nav;showEstimatedShares();status.innerHTML=`<b>${escapeHtml(data.name)}</b>（${data.code}）<br>最新单位净值 ${num(latest.nav,4)} · 净值日期 ${latest.date} · 最近日涨跌 ${pct(latest.daily_return)}`;status.className=`preset-fund-status ${tone(latest.daily_return)}`}catch(error){status.textContent=`查询失败：${error.message}`;status.className='preset-fund-status negative'}};
  $("preset-lookup").onclick=lookup;code.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();lookup()}};amountInput.oninput=showEstimatedShares;
  submit.onclick=async()=>{const message=$("preset-message"),fee=$("preset-sell-fee").value.trim();try{const result=await apiRequest("/api/v1/user/positions/preset",{method:"POST",body:JSON.stringify({fund_code:code.value.trim(),holding_amount:amountInput.value,pnl_direction:$("preset-pnl-direction").value,pnl_percent:$("preset-pnl-percent").value,sell_fee_percent:fee===""?null:fee})});message.textContent=`已添加 ${result.fund_name}，当前份额 ${num(result.shares,4)}，成本 ${money(result.cost_basis)}`;await loadUserPortfolio()}catch(e){message.textContent=e.message}};
}
setupPresetFundLookup();
function installUserAiTab(){
  const tabs=document.querySelector('.tabs'),userTab=document.querySelector('[data-tab="user"]'),userPane=$('tab-user');if(!tabs||!userTab||$('tab-user-ai'))return;
  userTab.insertAdjacentHTML('afterend','<button class="tab" data-tab="user-ai">我的独立 AI</button>');
  userPane.insertAdjacentHTML('afterend','<div id="tab-user-ai" class="tab-pane"><section class="login-prompt"><p class="eyebrow">PERSONAL AI PORTFOLIO</p><h2>我的独立 AI 组合</h2><p>独立于公共 AI 和你的手工账户；首次创建或同步会复制当前用户持仓。</p><button id="user-ai-create">创建 / 同步 AI 持仓</button><div id="user-ai-content" class="user-list"></div><div class="inline-fund-search"><input id="user-ai-prompt" placeholder="例如：分析当前持仓并决定独立 AI 是否需要调仓"><button id="user-ai-ask">让独立 AI 分析</button></div><div id="user-ai-answer" class="preset-fund-status"></div></section></div>');
  document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>{openTab(x.dataset.tab);if(x.dataset.tab==='user-ai')loadUserAi()});
  $('user-ai-create').onclick=async()=>{try{let result=await apiRequest('/api/v1/user/ai/sync',{method:'POST'});if(result.requires_confirmation){if(!confirm('同步会重置独立 AI 的持仓与操作记录，并复制你的当前持仓；对话上下文会保留。确认继续？'))return;result=await apiRequest('/api/v1/user/ai/sync?confirmed=true',{method:'POST'})}await loadUserAi()}catch(e){$('user-ai-answer').textContent=e.message}};
  $('user-ai-ask').onclick=async()=>{const answer=$('user-ai-answer');try{answer.textContent='独立 AI 正在分析…';const result=await apiRequest('/api/v1/user/ai/ask',{method:'POST',body:JSON.stringify({prompt:$('user-ai-prompt').value})});answer.textContent=result.answer;renderUserAi(result.portfolio)}catch(e){answer.textContent=e.message}};
}
function renderUserAi(data){const root=$('user-ai-content');if(!data.initialized){root.innerHTML='<div class="empty">尚未创建独立 AI 组合</div>';return}root.innerHTML=`<div class="user-summary"><article><span>AI 总资产</span><strong>${money(data.summary.total_assets)}</strong><small>创建后盈亏 ${money(data.summary.pnl)}</small></article><article><span>用户总资产</span><strong>${money(data.comparison.user_total_assets)}</strong><small>创建后盈亏 ${money(data.comparison.user_pnl)}</small></article><article><span>AI 现金</span><strong>${money(data.cash)}</strong><small>同步时间 ${data.synced_at.slice(0,16).replace('T',' ')}</small></article></div><h3>AI 当前持仓</h3>${data.positions.length?data.positions.map(p=>`<div class="user-row"><div><b>${p.fund_name}</b><span>${p.fund_code}</span></div><div>份额<b>${num(p.shares,4)}</b></div><div>市值<b>${money(p.market_value)}</b></div><div class="${tone(p.pnl)}">盈亏<b>${money(p.pnl)}</b></div></div>`).join(''):'<div class="empty">AI 当前无持仓</div>'}`}
function renderAiChat(data){const root=$('user-ai-chat-history');if(!root||!data.initialized)return;const rows=data.chat_history||[];root.innerHTML=rows.length?rows.map(item=>'<article class="ai-chat '+(item.role==='AI'?'ai':'user')+'"><b>'+escapeHtml(item.role)+'</b><p>'+escapeHtml(item.content).replace(/\n/g,'<br>')+'</p></article>').join(''):'<div class="empty">从下方开始提问，AI 会保留连续上下文。</div>';root.scrollTop=root.scrollHeight}
async function loadUserAi(){if(!signedInUser)return;try{const data=await apiRequest('/api/v1/user/ai');renderUserAi(data);renderAiChat(data)}catch(e){$('user-ai-content').textContent=e.message}}
installUserAiTab();
async function askUserAiStream(message,onStage){const streamUrl='/api/v1/user/ai/ask/stream',response=await fetch(streamUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:message})});if(!response.ok){let detail=`请求失败 (${response.status})`;try{detail=(await response.json()).detail||detail}catch{}throw new Error(`${detail} · ${streamUrl}`)}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',result=null;while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});let newline;while((newline=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,newline);buffer=buffer.slice(newline+1);if(!line)continue;const event=JSON.parse(line);if(event.type==='stage')onStage(event.message);else if(event.type==='result')result=event;else if(event.type==='error')throw new Error(event.detail||'独立 AI 分析异常')}if(done)break}if(!result)throw new Error('独立 AI 未返回最终结果');return result}
function bindContinuousUserAiChat(){const button=$('user-ai-ask'),input=$('user-ai-prompt'),status=$('user-ai-answer');if(!button||!input||!status)return;if(!$('user-ai-chat-history'))status.insertAdjacentHTML('beforebegin','<div id="user-ai-chat-history" class="ai-chat-history"></div>');const style=document.createElement('style');style.textContent='.ai-chat-history{max-height:420px;overflow:auto;text-align:left;margin:16px 0;padding:4px}.ai-chat{margin:10px 0;padding:10px 12px;border-radius:10px;background:#f2f5f3}.ai-chat.user{margin-left:12%;background:#e0f3e9}.ai-chat.ai{margin-right:12%}.ai-chat p{margin:5px 0 0;white-space:normal}';document.head.append(style);button.onclick=async()=>{const message=input.value.trim();if(!message)return;button.disabled=true;status.textContent='独立 AI 正在分析…';try{const result=await apiRequest('/api/v1/user/ai/ask',{method:'POST',body:JSON.stringify({prompt:message})});input.value='';status.textContent='';renderUserAi(result.portfolio);renderAiChat(result.portfolio)}catch(e){status.textContent=e.message}finally{button.disabled=false}};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();button.click()}}}
bindContinuousUserAiChat();
function enableAiProgressStream(){const button=$('user-ai-ask'),input=$('user-ai-prompt'),status=$('user-ai-answer');if(!button||!input||!status)return;button.onclick=async()=>{const message=input.value.trim();if(!message)return;button.disabled=true;try{const result=await askUserAiStream(message,text=>{status.textContent=text});input.value='';status.textContent='分析完成。';renderUserAi(result.portfolio);renderAiChat(result.portfolio)}catch(error){status.textContent=error.message}finally{button.disabled=false}};input.onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();button.click()}}}
enableAiProgressStream();
const baseRenderUserAi=renderUserAi;
renderUserAi=function(data){baseRenderUserAi(data);const syncButton=$('user-ai-create'),root=$('user-ai-content');if(!syncButton)return;if(!data.initialized){syncButton.textContent='创建独立 AI 持仓';return}syncButton.textContent='同步 AI 持仓';if(!$('user-ai-clear-context')){syncButton.insertAdjacentHTML('afterend','<button id="user-ai-clear-context" class="auth-link" style="margin-left:12px">清空对话上下文</button><button id="user-ai-delete" class="auth-link" style="margin-left:12px">删除独立 AI</button>');$('user-ai-clear-context').onclick=async()=>{if(!confirm('仅清空独立 AI 的历史对话与上下文，持仓和操作记录会保留。确认继续？'))return;try{await apiRequest('/api/v1/user/ai/context?confirmed=true',{method:'DELETE'});$('user-ai-answer').textContent='对话上下文已清空，持仓与操作记录未改变。';await loadUserAi()}catch(e){$('user-ai-answer').textContent=e.message}};$('user-ai-delete').onclick=async()=>{if(!confirm('将删除该独立 AI 的会话上下文、持仓和操作记录；此操作不可恢复。确认删除？'))return;try{await apiRequest('/api/v1/user/ai?confirmed=true',{method:'DELETE'});$('user-ai-answer').textContent='独立 AI 已删除，可重新创建。';await loadUserAi()}catch(e){$('user-ai-answer').textContent=e.message}}}root.closest('.login-prompt')?.classList.add('user-ai-ready')};
async function toggleAiFundDetail(row,code){const next=row.nextElementSibling;if(next?.classList.contains('ai-fund-detail')){next.remove();return}document.querySelectorAll('.ai-fund-detail').forEach(x=>x.remove());const detail=document.createElement('div');detail.className='ai-fund-detail';detail.textContent='正在读取基金详情…';row.insertAdjacentElement('afterend',detail);try{const fund=await fetchJson(`/api/v1/funds/${encodeURIComponent(code)}`);detail.innerHTML=`<b>${escapeHtml(fund.name)}</b> · ${fund.code}<div>最新净值 ${num(fund.latest.nav,4)}（${fund.latest.date}） · 日涨跌 ${pct(fund.latest.daily_return)}</div><div>近1周 ${pct(fund.returns.one_week)} · 近1月 ${pct(fund.returns.one_month)} · 近3月 ${pct(fund.returns.three_months)} · 近1年 ${pct(fund.returns.one_year)}</div><button class="ai-detail-chart">在基金页查看完整走势</button>`;detail.querySelector('.ai-detail-chart').onclick=()=>loadFund(code,true)}catch(e){detail.textContent=`基金详情暂不可用：${e.message}`}}
function renderAiComparison(data){const root=$('user-ai-comparison');if(!root||!(data.daily||[]).length)return;const rows=data.daily,base=Math.min(...rows.map(x=>Math.min(Number(x.ai_pnl),Number(x.user_pnl))),0),top=Math.max(...rows.map(x=>Math.max(Number(x.ai_pnl),Number(x.user_pnl))),1),w=700,h=190;const point=(v,i)=>`${i*(w/Math.max(rows.length-1,1))},${h-15-(Number(v)-base)/(top-base||1)*(h-35)}`;root.innerHTML=`<h3>用户与独立 AI 累计盈亏对比</h3><div class="user-summary"><article><span>用户累计盈亏</span><strong class="${tone(data.comparison.user_pnl)}">${money(data.comparison.user_pnl)}</strong></article><article><span>AI 累计盈亏</span><strong class="${tone(data.summary.pnl)}">${money(data.summary.pnl)}</strong></article><article><span>当前估值尾差</span><strong class="flat">${money(data.comparison.ai_relative_to_user)}</strong><small>份额与净值精度差异，非收益</small></article></div><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline fill="none" stroke="#35b980" stroke-width="3" points="${rows.map((x,i)=>point(x.user_pnl,i)).join(' ')}"/><polyline fill="none" stroke="#365be8" stroke-width="3" points="${rows.map((x,i)=>point(x.ai_pnl,i)).join(' ')}"/></svg><small><i style="color:#35b980">●</i> 用户累计盈亏　<i style="color:#365be8">●</i> 独立 AI 累计盈亏（自创建/同步日起）</small>`}
const clickableAiPositionRender=renderUserAi;
renderUserAi=function(data){clickableAiPositionRender(data);if(!data.initialized)return;const rows=document.querySelectorAll('#user-ai-content .user-row');rows.forEach((row,index)=>{const position=data.positions[index],target=row.firstElementChild;if(!position||!target)return;target.classList.add('ai-fund-link');target.title='点击展开基金详情';target.onclick=()=>toggleAiFundDetail(row,position.fund_code)});};
const aiFundLinkStyle=document.createElement('style');aiFundLinkStyle.textContent='.ai-fund-link{cursor:pointer}.ai-fund-link b{color:var(--green);text-decoration:underline;text-underline-offset:3px}.ai-fund-detail{margin:-3px 0 8px;padding:12px;border-radius:10px;background:#f4f8f6;color:var(--muted);font-size:12px;line-height:1.8}.ai-fund-detail b{color:var(--ink)}.ai-detail-chart{margin-top:8px;border:0;border-radius:7px;background:var(--ink);color:#fff;padding:6px 10px;cursor:pointer}';document.head.append(aiFundLinkStyle);
const comparisonAwareAiRender=renderUserAi;
renderUserAi=function(data){comparisonAwareAiRender(data);if(!data.initialized)return;const content=$('user-ai-content');if(!$('user-ai-comparison'))content.insertAdjacentHTML('beforebegin','<section id="user-ai-comparison" class="panel"></section>');renderAiComparison(data)};
function aiOperationLabel(status){return {completed:'已执行',pending:'已提交买入，等待基金净值确认',PENDING:'已提交买入，等待基金净值确认',PENDING_NAV:'等待基金净值确认',pending_nav_confirmation:'等待基金净值确认',pending_confirmation:'已提交买入，等待基金净值确认',booked_pending_nav_confirmation:'已提交，等待基金净值确认',cancelled_not_confirmed:'已取消',cancelled:'已取消'}[status]||'处理中'}
function aiActionLabel(action){return {subscribe_by_conversion:'转换转入',redeem_partial_for_conversion:'转换转出',subscribe:'买入',redeem_all:'全部卖出',redeem_partial:'部分卖出'}[action]||escapeHtml(action||'操作')}
function aiOperationReason(operation){const reasons={portfolio_rebalance_review_no_trade:'已按最新净值复核持仓：军工与卫星主题合计仓位处于既定上限内；为避免在亏损时无目标地卖出，暂不执行转换，等待明确的宽基或防守型配置目标。',risk_reduction_redemption:'卫星主题已全部赎回，军工主题已减仓一半，以降低高波动主题的集中风险；所得资金暂留现金，等待分批配置。',core_allocation_reinvestment:'将部分现金分批配置至稳健回报与成长甄选，保留主要现金仓位，避免一次性追涨或因亏损补仓。',core_position_build:'用部分现金建立防守与成长核心仓，不增加军工仓位；后续仍按分批策略执行。',staged_core_rebalance:'完成第二批核心仓配置：兼顾防守与成长，同时保留充足现金，等待下一次净值更新后再评估。',core_diversification_conversion:'将部分成长甄选转换至沪深300宽基仓；目标基金尚待净值确认，确认后才会折算份额并进入持仓。',ledger_reconciliation:'已恢复一笔标记为“未确认取消”的历史模拟转换对原基金份额和成本的错误影响；不改变待确认的沪深300转换订单。',rounding_residue_reconciliation:'已冲回旧模拟记录产生的账务尾差；该金额不是手续费、收益或亏损。'};return reasons[operation.type]||operation.reason||operation.recommended_next_action||'—'}
function aiSideLabel(side){return {buy:'买入',sell:'卖出',redeem:'赎回',hold:'继续持有'}[String(side||'').toLowerCase()]||'操作'}
function aiPendingNext(order){const specific={006131:'建立沪深300宽基核心仓，确认净值后自动折算份额；若到期未受理或市场出现明显追涨风险，则自动取消并复核。',006485:'配置中短债防守仓，确认净值后自动折算份额；若到期未受理或利率环境明显变化，则自动取消并复核。'};return specific[order.fund_code]||'无需你手动确认；等待下一交易日净值后自动折算份额并计入 AI 持仓。'}
function renderAiOperationDetail(operation){if(operation.fund_code){return `<b>${aiSideLabel(operation.side)} ${escapeHtml(operation.fund_name||operation.fund_code)}</b><span>${escapeHtml(operation.fund_code)} · 金额 ${operation.amount?money(operation.amount):'—'}${operation.nav?` · 净值 ${num(operation.nav,4)}`:''}${operation.shares?` · 份额 ${num(operation.shares,4)}`:''}</span><small>${escapeHtml(aiOperationReason(operation))}</small>`}const transactions=operation.transactions||[];if(transactions.length){return transactions.map(item=>`<b>${aiActionLabel(item.action)} ${escapeHtml(item.fund_name||item.fund_code||'')}</b><span>${escapeHtml(item.fund_code||'')} · ${item.amount?`金额 ${money(item.amount)}`:''}${item.shares?` · 份额 ${num(item.shares,4)}`:''}${item.nav?` · 净值 ${num(item.nav,4)}`:''}</span>`).join('')+`<small>${escapeHtml(aiOperationReason(operation))}</small>`}return `<b>${escapeHtml(aiOperationReason(operation))}</b>`}
const statusAwareAiRender=renderUserAi;
renderUserAi=function(data){statusAwareAiRender(data);if(!data.initialized)return;const content=$('user-ai-content'),parent=content.closest('.login-prompt');parent?.querySelectorAll('.user-ai-ledger-status').forEach(node=>node.remove());const pending=(data.pending_orders||[]).filter(order=>!String(order.status||'').toLowerCase().includes('cancel')),operations=(data.operations||[]).filter(operation=>!String(operation.status||'').toLowerCase().includes('cancel')).slice().sort((a,b)=>String(b.completed_at||b.timestamp||'').localeCompare(String(a.completed_at||a.timestamp||'')));let html='';if(pending.length){html+=`<section class="panel user-ai-ledger-status"><h3>已提交，等待基金确认</h3><p class="quiet">无需手动确认；下一交易日净值可用后将自动折算份额。</p>${pending.map(order=>`<div class="user-row"><div><b>${escapeHtml(order.fund_name||order.fund_code||'基金订单')}</b><span>${escapeHtml(order.fund_code||'')}</span></div><div>${order.action?aiActionLabel(order.action):aiSideLabel(order.side)}<b>${order.amount?money(order.amount):'—'}</b><span>资金来源：${escapeHtml(order.source_fund_code||'AI 可用现金')}${order.source_shares_redeemed?` · 约 ${num(order.source_shares_redeemed,4)} 份`:''}</span></div><div>状态<b>${aiOperationLabel(order.status||'pending')}</b></div><div>下一步<b>${aiPendingNext(order)}</b></div></div>`).join('')}</section>`}if(operations.length){html+=`<section class="panel user-ai-ledger-status"><h3>最近 AI 操作记录</h3>${operations.slice(0,5).map(operation=>`<div class="user-row"><div><b>${escapeHtml(operation.fund_code?'基金交易':({ledger_reconciliation:'账本核对修正',rounding_residue_reconciliation:'账务尾差冲回',core_diversification_conversion:'核心仓转换',staged_core_rebalance:'分批调仓',core_position_build:'建立核心仓',core_allocation_reinvestment:'核心仓再配置',risk_reduction_redemption:'风险降低赎回',portfolio_rebalance_review_no_trade:'持仓复核'}[operation.type]||operation.type||'AI 操作'))}</b><span>${escapeHtml(String(operation.completed_at||operation.timestamp||'').replace('T',' ').slice(0,16))}</span></div><div>状态<b>${aiOperationLabel(operation.status)}</b></div><div class="ai-operation-detail" style="grid-column:span 2">${renderAiOperationDetail(operation)}</div></div>`).join('')}</section>`}if(html)content.insertAdjacentHTML('beforebegin',html)};
fetch('/api/v1/portfolio').then(async r=>{if(!r.ok)throw new Error((await r.json()).detail||'读取失败');return r.json()}).then(data=>{renderPortfolio(data);renderDecisions(data.decisions)}).catch(e=>{$("loading").innerHTML=`<b>账本加载失败</b><br><span>${e.message}</span>`});
